\begin{lemma}
\label{lemma-weakly-ass-quotient-ring}
Soit $R$ un anneau.
Soit $I$ un idéal.
Soit $M$ un $R/I$-module.
Par l'injection canonique
$\Spec(R/I) \to \Spec(R)$
on a $\text{WeakAss}_{R/I}(M) = \text{WeakAss}_R(M)$.
\end{lemma}

\begin{proof}
C'est un cas particulier du Lemme \ref{lemma-weakly-ass-finite-ring-map}.
\end{proof}

